--
-- Name: api_key_usage_log; Type: TABLE; Schema: public; Owner: admin-rsi-metabase
--

CREATE TABLE public.api_key_usage_log (
    id bigint NOT NULL,
    api_key_id integer NOT NULL,
    user_id integer,
    created_by_id integer,
    route_template character varying(255) NOT NULL,
    http_method character varying(10) NOT NULL,
    status integer NOT NULL,
    duration_ms integer NOT NULL,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    ip_address character varying(45),
    user_agent character varying(512),
    client_name character varying(255) NOT NULL,
    embedding_client character varying(255),
    embedding_hostname character varying(512)
);


ALTER TABLE public.api_key_usage_log OWNER TO "admin-rsi-metabase";

--
-- Name: TABLE api_key_usage_log; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON TABLE public.api_key_usage_log IS 'One row per API-key-authenticated request; user and key creator denormalized on so the view needs no api_key join (modeled on agent_api_call_log)';


--
-- Name: COLUMN api_key_usage_log.id; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.api_key_usage_log.id IS 'Autoincrement primary key';


--
-- Name: COLUMN api_key_usage_log.api_key_id; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.api_key_usage_log.api_key_id IS 'The API key that authenticated the request. Deliberately not a foreign key so deleting a key does not cascade away its usage history.';


--
-- Name: COLUMN api_key_usage_log.user_id; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.api_key_usage_log.user_id IS 'The API key''s own synthetic service-account user, resolved at request time; NULL when the key has no user. Used for permission checks, not a real person. Not a foreign key, for the same reason as api_key_id. Non-PII.';


--
-- Name: COLUMN api_key_usage_log.created_by_id; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.api_key_usage_log.created_by_id IS 'The real human who created the API key, resolved from the same auth query as user_id; NULL when the key has no user. Not a foreign key, for the same reason as api_key_id. Non-PII.';


--
-- Name: COLUMN api_key_usage_log.route_template; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.api_key_usage_log.route_template IS 'Reconstructed route template of the request, e.g. /api/card/:id. Never the raw URI or query string. Non-PII.';


--
-- Name: COLUMN api_key_usage_log.http_method; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.api_key_usage_log.http_method IS 'HTTP method of the request, e.g. GET or POST. Non-PII.';


--
-- Name: COLUMN api_key_usage_log.status; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.api_key_usage_log.status IS 'HTTP status code of the response. Non-PII. Streamed responses (for example query results) always store 202, because the real status is only known after the stream ends, so do not read 202 as an outcome.';


--
-- Name: COLUMN api_key_usage_log.duration_ms; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.api_key_usage_log.duration_ms IS 'Wall-clock duration of the request in milliseconds';


--
-- Name: COLUMN api_key_usage_log.occurred_at; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.api_key_usage_log.occurred_at IS 'When the request happened, captured on the request thread. The default is a fallback only — the recorder always sets this explicitly, since the row itself may not land in the table until a scheduled flush later.';


--
-- Name: COLUMN api_key_usage_log.ip_address; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.api_key_usage_log.ip_address IS 'Client IP captured at request time, PII (gated by analytics-pii-retention-enabled).';


--
-- Name: COLUMN api_key_usage_log.user_agent; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.api_key_usage_log.user_agent IS 'Raw User-Agent header captured at request time, PII (gated by analytics-pii-retention-enabled).';


--
-- Name: COLUMN api_key_usage_log.client_name; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.api_key_usage_log.client_name IS 'Caller classified from the raw User-Agent (metabase-cli, curl, postman, python-requests, r, node, or other). Non-PII, always recorded — distinct from the raw, PII-gated user_agent column.';


--
-- Name: COLUMN api_key_usage_log.embedding_client; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.api_key_usage_log.embedding_client IS 'Raw X-Metabase-Client header value, when present. Non-PII, same status as view_log/query_execution.embedding_client. Supplementary to client_name (the primary classification axis) — almost never set on API-key traffic, since the SDK/embed.js clients that send it authenticate via JWT/SSO, not API keys.';


--
-- Name: COLUMN api_key_usage_log.embedding_hostname; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.api_key_usage_log.embedding_hostname IS 'Hostname parsed from the embed referrer header, when present. Non-PII, same status as view_log/query_execution/metabot_conversation.embedding_hostname. Only meaningful alongside embedding_client.';


--
-- Name: api_key_usage_log_id_seq; Type: SEQUENCE; Schema: public; Owner: admin-rsi-metabase
--

ALTER TABLE public.api_key_usage_log ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.api_key_usage_log_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


