--
-- Name: content_diagnostics_finding; Type: TABLE; Schema: public; Owner: admin-rsi-metabase
--

CREATE TABLE public.content_diagnostics_finding (
    id integer NOT NULL,
    scan_id character varying(36) NOT NULL,
    entity_type character varying(32) NOT NULL,
    entity_id integer NOT NULL,
    finding_type character varying(32) NOT NULL,
    scope_collection_id integer,
    details text,
    detected_at timestamp with time zone DEFAULT now() NOT NULL,
    invalidated_at timestamp with time zone,
    last_active_at timestamp with time zone,
    entity_name text,
    entity_created_at timestamp with time zone,
    entity_creator_id integer,
    entity_creator_name text,
    duration_ms bigint,
    content_count bigint,
    duplicate_count bigint,
    card_type character varying(32),
    entity_collection_name text,
    entity_kind character varying(32)
);


ALTER TABLE public.content_diagnostics_finding OWNER TO "admin-rsi-metabase";

--
-- Name: TABLE content_diagnostics_finding; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON TABLE public.content_diagnostics_finding IS 'One detected problem for one entity, from one scan run.';


--
-- Name: COLUMN content_diagnostics_finding.scan_id; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.content_diagnostics_finding.scan_id IS 'Groups all rows from one scan run (UUID). API serves the newest scan.';


--
-- Name: COLUMN content_diagnostics_finding.entity_type; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.content_diagnostics_finding.entity_type IS 'Polymorphic — card/dashboard/document/collection/transform. No FK.';


--
-- Name: COLUMN content_diagnostics_finding.entity_id; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.content_diagnostics_finding.entity_id IS 'Polymorphic id of the flagged entity (no FK; paired with entity_type).';


--
-- Name: COLUMN content_diagnostics_finding.finding_type; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.content_diagnostics_finding.finding_type IS 'stale/duplicated/empty/crowded/sparse/slow/trash-not-emptied';


--
-- Name: COLUMN content_diagnostics_finding.scope_collection_id; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.content_diagnostics_finding.scope_collection_id IS 'collection the entity lived in at scan time (filter/sort); no FK';


--
-- Name: COLUMN content_diagnostics_finding.details; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.content_diagnostics_finding.details IS 'JSON evidence — e.g. {threshold_days, last_active_at}';


--
-- Name: COLUMN content_diagnostics_finding.detected_at; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.content_diagnostics_finding.detected_at IS 'When this finding was detected (per-finding freshness signal).';


--
-- Name: COLUMN content_diagnostics_finding.invalidated_at; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.content_diagnostics_finding.invalidated_at IS 'stamped when invalidated/superseded; null = active (drives the served-set filter)';


--
-- Name: COLUMN content_diagnostics_finding.last_active_at; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.content_diagnostics_finding.last_active_at IS 'Entity''s last activity at scan time (card last_used_at / dashboard last_viewed_at); null = never used/ran. Frozen verdict evidence; powers the threshold-days serve filter.';


--
-- Name: COLUMN content_diagnostics_finding.entity_name; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.content_diagnostics_finding.entity_name IS 'Entity''s name at scan time; served as entity_display_name and used as the sort/search key. text because upstream names are unbounded.';


--
-- Name: COLUMN content_diagnostics_finding.entity_created_at; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.content_diagnostics_finding.entity_created_at IS 'Entity''s created_at (immutable). Denormalized for sort + display.';


--
-- Name: COLUMN content_diagnostics_finding.entity_creator_id; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.content_diagnostics_finding.entity_creator_id IS 'Entity''s creator_id at scan time; no FK (polymorphic, mirrors entity_id). Sort key (groups by creator).';


--
-- Name: COLUMN content_diagnostics_finding.entity_creator_name; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.content_diagnostics_finding.entity_creator_name IS 'Creator''s common_name at scan time (resolved from creator_id). Sort key for created-by, served in details.creator. text because common_name can be an email, which is unbounded on Postgres.';


--
-- Name: COLUMN content_diagnostics_finding.duration_ms; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.content_diagnostics_finding.duration_ms IS 'Verdict magnitude for slow findings - median query ms (card) / last-run ms (transform) / slowest-child ms (dashboard/document roll-up); null on all other finding types (per-type named magnitude column). bigint, not int - a pathological run duration can exceed 2^31-1 ms.';


--
-- Name: COLUMN content_diagnostics_finding.content_count; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.content_diagnostics_finding.content_count IS 'Verdict magnitude for imbalanced (empty/sparse/crowded) findings - items (collection) / dashcards or tabs (dashboard) / cards (document) / rows (card, transform); 0 on every empty finding, null on all other finding types (per-type named magnitude column). bigint - house choice for magnitude columns.';


--
-- Name: COLUMN content_diagnostics_finding.duplicate_count; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.content_diagnostics_finding.duplicate_count IS 'Verdict magnitude for duplicated findings - the number of other same-type entities sharing the normalized name (cluster size minus 1); null on all other finding types (per-type named magnitude column).';


--
-- Name: COLUMN content_diagnostics_finding.card_type; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.content_diagnostics_finding.card_type IS 'report_card.type (question/model/metric) at scan time, card findings only; null on all other entity types. Denormalized filter key for the card sub-kind values of the entity-types param (mutable upstream - drift until the next scan, like entity_name).';


--
-- Name: COLUMN content_diagnostics_finding.entity_collection_name; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.content_diagnostics_finding.entity_collection_name IS 'Scan-time name of the scope_collection_id collection (root rows store the root label); sort/display value for the collection column.';


--
-- Name: COLUMN content_diagnostics_finding.entity_kind; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.content_diagnostics_finding.entity_kind IS 'Flat entity kind at scan time - card_type for cards, else entity_type; serves the entity-types filter and entity-type sort.';


--
-- Name: content_diagnostics_finding_id_seq; Type: SEQUENCE; Schema: public; Owner: admin-rsi-metabase
--

ALTER TABLE public.content_diagnostics_finding ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.content_diagnostics_finding_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


