--

COMMENT ON COLUMN public.impersonation_query_cache.input_query IS 'Native SQL of the stage after parameter substitution';


--
-- Name: COLUMN impersonation_query_cache.result; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.impersonation_query_cache.result IS 'Validation outcome: valid, unparseable, unvalidatable or invalid';


