--
-- Name: v_agent_api_calls; Type: VIEW; Schema: public; Owner: admin-rsi-metabase
--

CREATE VIEW public.v_agent_api_calls AS
 SELECT t.id AS call_id,
    t.created_at,
    t.operation,
    t.status,
    t.error_message,
    t.duration_ms,
    t.user_id,
    COALESCE((((u.first_name)::text || ' '::text) || (u.last_name)::text), (u.email)::text) AS user_display_name,
    ( SELECT pg.name
           FROM (public.permissions_group_membership pgm
             JOIN public.permissions_group pg ON ((pg.id = pgm.group_id)))
          WHERE ((pgm.user_id = t.user_id) AND (pg.id <> 1))
          ORDER BY pg.name
         LIMIT 1) AS group_name,
    t.client_name,
        CASE t.client_name
            WHEN 'metabase-cli'::text THEN 'Metabase CLI'::character varying
            WHEN 'other'::text THEN 'Other'::character varying
            ELSE t.client_name
        END AS client_display_name,
    t.tenant_id,
    tn.name AS tenant_name,
    t.ip_address
   FROM ((public.agent_api_call_log t
     LEFT JOIN public.core_user u ON ((u.id = t.user_id)))
     LEFT JOIN public.tenant tn ON ((tn.id = t.tenant_id)));


ALTER VIEW public.v_agent_api_calls OWNER TO "admin-rsi-metabase";

--
-- Name: v_ai_usage_log; Type: VIEW; Schema: public; Owner: admin-rsi-metabase
--

CREATE VIEW public.v_ai_usage_log AS
 SELECT a.id AS usage_log_id,
    a.created_at,
    a.source,
        CASE a.source
            WHEN 'metabot_agent'::text THEN 'Metabot'::character varying
            WHEN 'agent'::text THEN 'Metabot'::character varying
            WHEN 'contextual_interestingness'::text THEN 'Research'::character varying
            WHEN 'exploration'::text THEN 'Research'::character varying
            WHEN 'document_generate_content'::text THEN 'Documents'::character varying
            WHEN 'example_question_generation_batch'::text THEN 'Suggested Prompts'::character varying
            WHEN 'conversation_title'::text THEN 'Conversation titles'::character varying
            WHEN 'slack'::text THEN 'Slackbot'::character varying
            WHEN 'slackbot'::text THEN 'Slackbot'::character varying
            WHEN 'oss-sql-gen'::text THEN 'SQL'::character varying
            WHEN 'sql-gen'::text THEN 'SQL'::character varying
            WHEN 'unknown'::text THEN 'Unknown'::character varying
            ELSE a.source
        END AS source_name,
    a.model,
    a.profile_id,
    a.prompt_tokens,
    a.completion_tokens,
    a.total_tokens,
    a.conversation_id,
    a.user_id,
    ('user_'::text || a.user_id) AS user_qualified_id,
    COALESCE((((u.first_name)::text || ' '::text) || (u.last_name)::text), (u.email)::text) AS user_display_name,
    ( SELECT pg.name
           FROM (public.permissions_group_membership pgm
             JOIN public.permissions_group pg ON ((pg.id = pgm.group_id)))
          WHERE ((pgm.user_id = a.user_id) AND (pg.id <> 1))
          ORDER BY pg.name
         LIMIT 1) AS group_name,
    c.ip_address,
    c.embedding_hostname,
    c.embedding_path,
    c.user_agent,
    c.sanitized_user_agent,
    c.forked_from_conversation_id,
    a.tenant_id,
    a.request_id,
    a.cache_creation_tokens,
    a.cache_read_tokens
   FROM ((public.ai_usage_log a
     LEFT JOIN public.core_user u ON ((u.id = a.user_id)))
     LEFT JOIN public.metabot_conversation c ON (((c.id)::text = (a.conversation_id)::text)));


ALTER VIEW public.v_ai_usage_log OWNER TO "admin-rsi-metabase";

--
-- Name: v_alerts; Type: VIEW; Schema: public; Owner: admin-rsi-metabase
--

CREATE VIEW public.v_alerts AS
 WITH parsed_cron AS (
         SELECT n_1.id,
            ns.cron_schedule,
            ns.ui_display_type,
            split_part((ns.cron_schedule)::text, ' '::text, 2) AS minutes,
            split_part((ns.cron_schedule)::text, ' '::text, 3) AS hours,
            split_part((ns.cron_schedule)::text, ' '::text, 4) AS day_of_month,
            split_part((ns.cron_schedule)::text, ' '::text, 6) AS day_of_week
           FROM (public.notification n_1
             JOIN public.notification_subscription ns ON ((n_1.id = ns.notification_id)))
          WHERE (((n_1.payload_type)::text = 'notification/card'::text) AND ((ns.type)::text = 'notification-subscription/cron'::text))
        ), schedule_info AS (
         SELECT parsed_cron.id,
                CASE
                    WHEN ((parsed_cron.ui_display_type)::text = 'cron/raw'::text) THEN 'custom'::text
                    WHEN ((parsed_cron.minutes ~ '^\*$'::text) OR (parsed_cron.minutes ~ '^\d+/\d+$'::text)) THEN 'by the minute'::text
                    WHEN ((parsed_cron.day_of_month <> '*'::text) AND ((parsed_cron.day_of_week = '?'::text) OR (parsed_cron.day_of_week ~ '^\d#1$'::text) OR (parsed_cron.day_of_week ~ '^\dL$'::text))) THEN 'monthly'::text
                    WHEN ((parsed_cron.day_of_week <> '?'::text) AND (parsed_cron.day_of_week <> '*'::text)) THEN 'weekly'::text
                    WHEN (parsed_cron.hours <> '*'::text) THEN 'daily'::text
                    ELSE 'hourly'::text
                END AS schedule_type,
                CASE
                    WHEN (parsed_cron.day_of_week ~ '^1'::text) THEN 'sun'::text
                    WHEN (parsed_cron.day_of_week ~ '^2'::text) THEN 'mon'::text
                    WHEN (parsed_cron.day_of_week ~ '^3'::text) THEN 'tue'::text
                    WHEN (parsed_cron.day_of_week ~ '^4'::text) THEN 'wed'::text
                    WHEN (parsed_cron.day_of_week ~ '^5'::text) THEN 'thu'::text
                    WHEN (parsed_cron.day_of_week ~ '^6'::text) THEN 'fri'::text
                    WHEN (parsed_cron.day_of_week ~ '^7'::text) THEN 'sat'::text
                    ELSE NULL::text
                END AS schedule_day,
                CASE
                    WHEN (parsed_cron.hours = '*'::text) THEN NULL::integer
                    WHEN (parsed_cron.hours ~ '^\d+$'::text) THEN (parsed_cron.hours)::integer
                    WHEN (parsed_cron.hours ~ '^(\d+)/\d+$'::text) THEN ("substring"(parsed_cron.hours, '^(\d+)/\d+$'::text))::integer
                    ELSE NULL::integer
                END AS schedule_hour
           FROM parsed_cron
        ), agg_recipients AS (
         SELECT nr.notification_handler_id,
            string_agg((cu.email)::text, ','::text) AS recipients,
            ( SELECT string_agg(nr2.details, ','::text) AS string_agg
                   FROM public.notification_recipient nr2
                  WHERE ((nr2.notification_handler_id = nr.notification_handler_id) AND ((nr2.type)::text = 'notification-recipient/raw-value'::text))) AS recipient_external
           FROM (public.notification_recipient nr
             LEFT JOIN public.core_user cu ON (((nr.user_id = cu.id) AND ((nr.type)::text = 'notification-recipient/user'::text))))
          GROUP BY nr.notification_handler_id
        )
 SELECT n.id AS entity_id,
    ('notification_'::text || n.id) AS entity_qualified_id,
    n.created_at,
    n.updated_at,
    n.creator_id,
    nc.card_id,
    ('card_'::text || nc.card_id) AS card_qualified_id,
        CASE
            WHEN ((nc.send_condition)::text = 'has_result'::text) THEN 'rows'::text
            WHEN ((nc.send_condition)::text = ANY (ARRAY[('goal_above'::character varying)::text, ('goal_below'::character varying)::text])) THEN 'goal'::text
            ELSE NULL::text
        END AS alert_condition,
    si.schedule_type,
    si.schedule_day,
    si.schedule_hour,
    (NOT n.active) AS archived,
    nh.channel_type AS recipient_type,
    ar.recipients,
    ar.recipient_external
   FROM ((((public.notification n
     JOIN public.notification_card nc ON ((n.payload_id = nc.id)))
     JOIN schedule_info si ON ((n.id = si.id)))
     LEFT JOIN public.notification_handler nh ON ((n.id = nh.notification_id)))
     LEFT JOIN agg_recipients ar ON ((nh.id = ar.notification_handler_id)))
  WHERE ((n.payload_type)::text = 'notification/card'::text);


ALTER VIEW public.v_alerts OWNER TO "admin-rsi-metabase";

--
-- Name: v_api_key_usage; Type: VIEW; Schema: public; Owner: admin-rsi-metabase
--

CREATE VIEW public.v_api_key_usage AS
 SELECT t.id AS log_id,
    t.occurred_at,
    t.route_template,
    t.http_method,
    t.status,
    t.duration_ms,
    t.api_key_id,
    ak.name AS api_key_name,
    t.user_id AS actor_user_id,
    t.created_by_id AS creator_id,
    COALESCE((((creator.first_name)::text || ' '::text) || (creator.last_name)::text), (creator.email)::text) AS creator_display_name,
    ( SELECT pg.name
           FROM (public.permissions_group_membership pgm
             JOIN public.permissions_group pg ON ((pg.id = pgm.group_id)))
          WHERE (pgm.user_id = ak.user_id)
          ORDER BY
                CASE
                    WHEN (pg.id = 1) THEN 1
                    ELSE 0
                END, pg.name
         LIMIT 1) AS group_name,
    t.client_name,
        CASE t.client_name
            WHEN 'metabase-cli'::text THEN 'Metabase CLI'::character varying
            WHEN 'curl'::text THEN 'curl'::character varying
            WHEN 'postman'::text THEN 'Postman'::character varying
            WHEN 'python-requests'::text THEN 'Python'::character varying
            WHEN 'r'::text THEN 'R'::character varying
            WHEN 'node'::text THEN 'Node.js'::character varying
            WHEN 'other'::text THEN 'Other'::character varying
            ELSE t.client_name
        END AS client_display_name,
    t.embedding_client,
    t.embedding_hostname,
    t.ip_address,
    t.user_agent
   FROM ((public.api_key_usage_log t
     LEFT JOIN public.api_key ak ON ((ak.id = t.api_key_id)))
     LEFT JOIN public.core_user creator ON ((creator.id = t.created_by_id)));


ALTER VIEW public.v_api_key_usage OWNER TO "admin-rsi-metabase";

--
-- Name: v_audit_log; Type: VIEW; Schema: public; Owner: admin-rsi-metabase
--

CREATE VIEW public.v_audit_log AS
 SELECT id,
        CASE
            WHEN ((topic)::text = 'card-create'::text) THEN 'card-create'::character varying
            WHEN ((topic)::text = 'card-delete'::text) THEN 'card-delete'::character varying
            WHEN ((topic)::text = 'card-update'::text) THEN 'card-update'::character varying
            WHEN ((topic)::text = 'pulse-create'::text) THEN 'subscription-create'::character varying
            WHEN ((topic)::text = 'pulse-delete'::text) THEN 'subscription-delete'::character varying
            ELSE topic
        END AS topic,
    "timestamp",
    NULL::text AS end_timestamp,
    COALESCE(user_id, 0) AS user_id,
    lower((model)::text) AS entity_type,
    model_id AS entity_id,
        CASE
            WHEN ((model)::text = 'Dataset'::text) THEN ('card_'::text || model_id)
            WHEN (model_id IS NULL) THEN NULL::text
            ELSE ((lower((model)::text) || '_'::text) || model_id)
        END AS entity_qualified_id,
    details
   FROM public.audit_log
  WHERE ((topic)::text <> ALL (ARRAY[('card-read'::character varying)::text, ('card-query'::character varying)::text, ('dashboard-read'::character varying)::text, ('dashboard-query'::character varying)::text, ('table-read'::character varying)::text]));


ALTER VIEW public.v_audit_log OWNER TO "admin-rsi-metabase";

--
-- Name: v_content; Type: VIEW; Schema: public; Owner: admin-rsi-metabase
--

CREATE VIEW public.v_content AS
 SELECT action.id AS entity_id,
    ('action_'::text || action.id) AS entity_qualified_id,
    'action'::text AS entity_type,
    action.created_at,
    action.updated_at,
    action.creator_id,
    action.name,
    action.description,
    NULL::integer AS collection_id,
    action.made_public_by_id AS made_public_by_user,
    NULL::boolean AS is_embedding_enabled,
    NULL::boolean AS is_verified,
    action.archived,
    action.type AS action_type,
    action.model_id AS action_model_id,
    NULL::boolean AS collection_is_official,
    NULL::boolean AS collection_is_personal,
    NULL::text AS question_viz_type,
    NULL::text AS question_database_id,
    NULL::boolean AS question_is_native,
    NULL::timestamp without time zone AS event_timestamp
   FROM public.action
UNION
 SELECT collection.id AS entity_id,
    ('collection_'::text || collection.id) AS entity_qualified_id,
    'collection'::text AS entity_type,
    collection.created_at,
    NULL::timestamp with time zone AS updated_at,
    NULL::integer AS creator_id,
    collection.name,
    collection.description,
    NULL::integer AS collection_id,
    NULL::integer AS made_public_by_user,
    NULL::boolean AS is_embedding_enabled,
    NULL::boolean AS is_verified,
    collection.archived,
    NULL::text AS action_type,
    NULL::integer AS action_model_id,
        CASE
            WHEN ((collection.authority_level)::text = 'official'::text) THEN true
            ELSE false
        END AS collection_is_official,
        CASE
            WHEN (collection.personal_owner_id IS NOT NULL) THEN true
            ELSE false
        END AS collection_is_personal,
    NULL::text AS question_viz_type,
    NULL::text AS question_database_id,
    NULL::boolean AS question_is_native,
    NULL::timestamp without time zone AS event_timestamp
   FROM public.collection
UNION
 SELECT report_card.id AS entity_id,
    ('card_'::text || report_card.id) AS entity_qualified_id,
    report_card.type AS entity_type,
    report_card.created_at,
    report_card.updated_at,
    report_card.creator_id,
    report_card.name,
    report_card.description,
    report_card.collection_id,
    report_card.made_public_by_id AS made_public_by_user,
    report_card.enable_embedding AS is_embedding_enabled,
        CASE
            WHEN moderation.is_verified THEN true
            ELSE false
        END AS is_verified,
    report_card.archived,
    NULL::text AS action_type,
    NULL::integer AS action_model_id,
    NULL::boolean AS collection_is_official,
    NULL::boolean AS collection_is_personal,
    report_card.display AS question_viz_type,
    ('database_'::text || report_card.database_id) AS question_database_id,
        CASE
            WHEN ((report_card.query_type)::text = 'native'::text) THEN true
            ELSE false
        END AS question_is_native,
    NULL::timestamp without time zone AS event_timestamp
   FROM (public.report_card
     LEFT JOIN ( SELECT (((moderation_review.moderated_item_type)::text || '_'::text) || moderation_review.moderated_item_id) AS entity_qualified_id,
                CASE
                    WHEN ((moderation_review.status)::text = 'verified'::text) THEN true
                    ELSE false
                END AS is_verified
           FROM public.moderation_review
          WHERE moderation_review.most_recent) moderation ON ((('card_'::text || report_card.id) = moderation.entity_qualified_id)))
UNION
 SELECT report_dashboard.id AS entity_id,
    ('dashboard_'::text || report_dashboard.id) AS entity_qualified_id,
    'dashboard'::text AS entity_type,
    report_dashboard.created_at,
    report_dashboard.updated_at,
    report_dashboard.creator_id,
    report_dashboard.name,
    report_dashboard.description,
    report_dashboard.collection_id,
    report_dashboard.made_public_by_id AS made_public_by_user,
    report_dashboard.enable_embedding AS is_embedding_enabled,
        CASE
            WHEN moderation.is_verified THEN true
            ELSE false
        END AS is_verified,
    report_dashboard.archived,
    NULL::text AS action_type,
    NULL::integer AS action_model_id,
    NULL::boolean AS collection_is_official,
    NULL::boolean AS collection_is_personal,
    NULL::text AS question_viz_type,
    NULL::text AS question_database_id,
    NULL::boolean AS question_is_native,
    NULL::timestamp without time zone AS event_timestamp
   FROM (public.report_dashboard
     LEFT JOIN ( SELECT (((moderation_review.moderated_item_type)::text || '_'::text) || moderation_review.moderated_item_id) AS entity_qualified_id,
                CASE
                    WHEN ((moderation_review.status)::text = 'verified'::text) THEN true
                    ELSE false
                END AS is_verified
           FROM public.moderation_review
          WHERE moderation_review.most_recent) moderation ON ((('dashboard_'::text || report_dashboard.id) = moderation.entity_qualified_id)))
UNION
 SELECT document.id AS entity_id,
    ('document_'::text || document.id) AS entity_qualified_id,
    'document'::text AS entity_type,
    document.created_at,
    document.updated_at,
    document.creator_id,
    document.name,
    NULL::text AS description,
    document.collection_id,
    NULL::integer AS made_public_by_user,
    NULL::boolean AS is_embedding_enabled,
    NULL::boolean AS is_verified,
    document.archived,
    NULL::text AS action_type,
    NULL::integer AS action_model_id,
    NULL::boolean AS collection_is_official,
    NULL::boolean AS collection_is_personal,
    NULL::text AS question_viz_type,
    NULL::text AS question_database_id,
    NULL::boolean AS question_is_native,
    NULL::timestamp without time zone AS event_timestamp
   FROM public.document
  WHERE (document.exploration_id IS NULL)
UNION
 SELECT exploration.id AS entity_id,
    ('exploration_'::text || exploration.id) AS entity_qualified_id,
    'exploration'::text AS entity_type,
    exploration.created_at,
    exploration.updated_at,
    exploration.creator_id,
    exploration.name,
    exploration.description,
    exploration.collection_id,
    NULL::integer AS made_public_by_user,
    NULL::boolean AS is_embedding_enabled,
    NULL::boolean AS is_verified,
    exploration.archived,
    NULL::text AS action_type,
    NULL::integer AS action_model_id,
    NULL::boolean AS collection_is_official,
    NULL::boolean AS collection_is_personal,
    NULL::text AS question_viz_type,
    NULL::text AS question_database_id,
    NULL::boolean AS question_is_native,
    NULL::timestamp without time zone AS event_timestamp
   FROM public.exploration
UNION
 SELECT event.id AS entity_id,
    ('event_'::text || event.id) AS entity_qualified_id,
    'event'::text AS entity_type,
    event.created_at,
    event.updated_at,
    event.creator_id,
    event.name,
    event.description,
    timeline.collection_id,
    NULL::integer AS made_public_by_user,
    NULL::boolean AS is_embedding_enabled,
    NULL::boolean AS is_verified,
    event.archived,
    NULL::text AS action_type,
    NULL::integer AS action_model_id,
    NULL::boolean AS collection_is_official,
    NULL::boolean AS collection_is_personal,
    NULL::text AS question_viz_type,
    NULL::text AS question_database_id,
    NULL::boolean AS question_is_native,
    event."timestamp" AS event_timestamp
   FROM (public.timeline_event event
     LEFT JOIN public.timeline ON ((event.timeline_id = timeline.id)))
UNION
 SELECT transform.id AS entity_id,
    ('transform_'::text || transform.id) AS entity_qualified_id,
    'transform'::text AS entity_type,
    transform.created_at,
    transform.updated_at,
    transform.creator_id,
    transform.name,
    transform.description,
    NULL::integer AS collection_id,
    NULL::integer AS made_public_by_user,
    NULL::boolean AS is_embedding_enabled,
    NULL::boolean AS is_verified,
    false AS archived,
    NULL::text AS action_type,
    NULL::integer AS action_model_id,
    NULL::boolean AS collection_is_official,
    NULL::boolean AS collection_is_personal,
    NULL::text AS question_viz_type,
    NULL::text AS question_database_id,
    NULL::boolean AS question_is_native,
    NULL::timestamp without time zone AS event_timestamp
   FROM public.transform
UNION
 SELECT glossary.id AS entity_id,
    ('glossary_'::text || glossary.id) AS entity_qualified_id,
    'glossary'::text AS entity_type,
    glossary.created_at,
    glossary.updated_at,
    glossary.creator_id,
    glossary.term AS name,
    glossary.definition AS description,
    NULL::integer AS collection_id,
    NULL::integer AS made_public_by_user,
    NULL::boolean AS is_embedding_enabled,
    NULL::boolean AS is_verified,
    false AS archived,
    NULL::text AS action_type,
    NULL::integer AS action_model_id,
    NULL::boolean AS collection_is_official,
    NULL::boolean AS collection_is_personal,
    NULL::text AS question_viz_type,
    NULL::text AS question_database_id,
    NULL::boolean AS question_is_native,
    NULL::timestamp without time zone AS event_timestamp
   FROM public.glossary;


ALTER VIEW public.v_content OWNER TO "admin-rsi-metabase";

--
-- Name: v_dashboardcard; Type: VIEW; Schema: public; Owner: admin-rsi-metabase
--

CREATE VIEW public.v_dashboardcard AS
 SELECT id AS entity_id,
    concat('dashboardcard_', id) AS entity_qualified_id,
    concat('dashboard_', dashboard_id) AS dashboard_qualified_id,
    concat('dashboardtab_', dashboard_tab_id) AS dashboardtab_id,
    concat('card_', card_id) AS card_qualified_id,
    created_at,
    updated_at,
    size_x,
    size_y,
    visualization_settings,
    parameter_mappings
   FROM public.report_dashboardcard;


ALTER VIEW public.v_dashboardcard OWNER TO "admin-rsi-metabase";

--
-- Name: v_databases; Type: VIEW; Schema: public; Owner: admin-rsi-metabase
--

CREATE VIEW public.v_databases AS
 SELECT id AS entity_id,
    concat('database_', id) AS entity_qualified_id,
    created_at,
    updated_at,
    name,
    description,
    engine AS database_type,
    metadata_sync_schedule,
    cache_field_values_schedule,
    timezone,
    is_on_demand,
    auto_run_queries,
    cache_ttl,
    creator_id,
    dbms_version AS db_version
   FROM public.metabase_database
  WHERE (id <> 13371337);


ALTER VIEW public.v_databases OWNER TO "admin-rsi-metabase";

--
-- Name: v_fields; Type: VIEW; Schema: public; Owner: admin-rsi-metabase
--

CREATE VIEW public.v_fields AS
 SELECT f.id AS entity_id,
    ('field_'::text || f.id) AS entity_qualified_id,
    f.created_at,
    f.updated_at,
    f.name,
    COALESCE(u.display_name, f.display_name) AS display_name,
        CASE
            WHEN u.description_set THEN u.description
            ELSE f.description
        END AS description,
    f.base_type,
    COALESCE(u.visibility_type, f.visibility_type) AS visibility_type,
        CASE
            WHEN u.fk_target_field_id_set THEN u.fk_target_field_id
            ELSE f.fk_target_field_id
        END AS fk_target_field_id,
    COALESCE(u.has_field_values, f.has_field_values) AS has_field_values,
    f.active,
    f.table_id
   FROM (public.metabase_field f
     LEFT JOIN public.metabase_field_user_settings u ON ((u.field_id = f.id)));


ALTER VIEW public.v_fields OWNER TO "admin-rsi-metabase";

--
-- Name: v_group_members; Type: VIEW; Schema: public; Owner: admin-rsi-metabase
--

CREATE VIEW public.v_group_members AS
 SELECT permissions_group_membership.user_id,
    permissions_group.id AS group_id,
    permissions_group.name AS group_name
   FROM (public.permissions_group_membership
     LEFT JOIN public.permissions_group ON ((permissions_group_membership.group_id = permissions_group.id)))
UNION
 SELECT 0 AS user_id,
    0 AS group_id,
    'Anonymous users'::character varying AS group_name;


ALTER VIEW public.v_group_members OWNER TO "admin-rsi-metabase";

--
-- Name: v_mcp_tool_calls; Type: VIEW; Schema: public; Owner: admin-rsi-metabase
--

CREATE VIEW public.v_mcp_tool_calls AS
 SELECT t.id AS tool_call_id,
    t.created_at,
    t.tool_name,
    t.status,
        CASE t.error_code
            WHEN '-32600'::integer THEN 'Invalid request'::text
            WHEN '-32601'::integer THEN 'Method not found'::text
            WHEN '-32602'::integer THEN 'Invalid params'::text
            WHEN '-32603'::integer THEN 'Internal error'::text
            WHEN '-32000'::integer THEN 'Server error'::text
            ELSE NULL::text
        END AS error_type,
    t.error_message,
    t.duration_ms,
    t.user_id,
    COALESCE((((u.first_name)::text || ' '::text) || (u.last_name)::text), (u.email)::text) AS user_display_name,
    ( SELECT pg.name
           FROM (public.permissions_group_membership pgm
             JOIN public.permissions_group pg ON ((pg.id = pgm.group_id)))
          WHERE ((pgm.user_id = t.user_id) AND (pg.id <> 1))
          ORDER BY pg.name
         LIMIT 1) AS group_name,
    t.client_name,
        CASE t.client_name
            WHEN 'claude'::text THEN 'Claude'::character varying
            WHEN 'chatgpt'::text THEN 'ChatGPT'::character varying
            WHEN 'cursor-vscode'::text THEN 'Cursor'::character varying
            WHEN 'vscode'::text THEN 'VS Code'::character varying
            WHEN 'zed'::text THEN 'Zed'::character varying
            WHEN 'other'::text THEN 'Other'::character varying
            ELSE t.client_name
        END AS client_display_name,
    t.client_version,
    t.tenant_id,
    tn.name AS tenant_name,
    t.ip_address,
    t.user_agent,
    t.sanitized_user_agent
   FROM ((public.mcp_tool_call_log t
     LEFT JOIN public.core_user u ON ((u.id = t.user_id)))
     LEFT JOIN public.tenant tn ON ((tn.id = t.tenant_id)));


ALTER VIEW public.v_mcp_tool_calls OWNER TO "admin-rsi-metabase";

--
-- Name: v_metabot_conversations; Type: VIEW; Schema: public; Owner: admin-rsi-metabase
--

CREATE VIEW public.v_metabot_conversations AS
SELECT
    NULL::character varying(36) AS conversation_id,
    NULL::timestamp with time zone AS created_at,
    NULL::integer AS user_id,
    NULL::text AS title,
    NULL::text AS user_display_name,
    NULL::bigint AS message_count,
    NULL::bigint AS user_message_count,
    NULL::bigint AS assistant_message_count,
    NULL::bigint AS new_message_count,
    NULL::bigint AS total_tokens,
    NULL::bigint AS prompt_tokens,
    NULL::bigint AS completion_tokens,
    NULL::timestamp with time zone AS last_message_at,
    NULL::text AS profile_id,
    NULL::text AS profile_name,
    NULL::character varying(255) AS group_name,
    NULL::character varying(100) AS source,
    NULL::character varying AS source_name,
    NULL::character varying(45) AS ip_address,
    NULL::character varying(512) AS embedding_hostname,
    NULL::character varying(2048) AS embedding_path,
    NULL::character varying(512) AS user_agent,
    NULL::character varying(512) AS sanitized_user_agent,
    NULL::character varying(36) AS forked_from_conversation_id,
    NULL::integer AS tenant_id,
    NULL::text AS tenant_name,
    NULL::character varying(255) AS model;


ALTER VIEW public.v_metabot_conversations OWNER TO "admin-rsi-metabase";

--
-- Name: v_metabot_messages; Type: VIEW; Schema: public; Owner: admin-rsi-metabase
--

CREATE VIEW public.v_metabot_messages AS
 SELECT m.id AS message_id,
    m.conversation_id,
    m.created_at,
    m.role,
    m.profile_id,
    m.total_tokens,
    COALESCE(m.user_id, c.user_id) AS user_id,
    m.slack_msg_id,
    m.channel_id
   FROM (public.metabot_message m
     JOIN public.metabot_conversation c ON (((c.id)::text = (m.conversation_id)::text)))
  WHERE (m.forked_from_message_id IS NULL);


ALTER VIEW public.v_metabot_messages OWNER TO "admin-rsi-metabase";

--
-- Name: v_query_log; Type: VIEW; Schema: public; Owner: admin-rsi-metabase
--

CREATE VIEW public.v_query_log AS
 SELECT query_execution.id AS entity_id,
    query_execution.started_at,
    ((query_execution.running_time)::double precision / (1000)::double precision) AS running_time_seconds,
    query_execution.result_rows,
    query_execution.native AS is_native,
    query_execution.context AS query_source,
    query_execution.error,
    COALESCE(query_execution.executor_id, 0) AS user_id,
    query_execution.card_id,
    ('card_'::text || query_execution.card_id) AS card_qualified_id,
    query_execution.dashboard_id,
    ('dashboard_'::text || query_execution.dashboard_id) AS dashboard_qualified_id,
    query_execution.pulse_id,
    query_execution.database_id,
    ('database_'::text || query_execution.database_id) AS database_qualified_id,
    query_execution.cache_hit,
    query_execution.action_id,
    ('action_'::text || query_execution.action_id) AS action_qualified_id,
    query_execution.transform_id,
    ('transform_'::text || query_execution.transform_id) AS transform_qualified_id,
    query_execution.lens_id,
    query_execution.lens_params,
    query.query,
    query_execution.embedding_client,
    query_execution.embedding_client_identifier,
    query_execution.embedding_route,
        CASE
            WHEN ((query_execution.embedding_client)::text ~~ '%-preview'::text) THEN true
            ELSE false
        END AS is_preview,
    query_execution.embedding_sdk_version,
    query_execution.metabase_version,
    query_execution.auth_method,
    query_execution.is_sandboxed,
    query_execution.sandbox_details,
    query_execution.is_impersonated,
    query_execution.is_db_routed,
    query_execution.parameters,
    query_execution.tenant_id,
    query_execution.embedding_hostname,
    query_execution.embedding_path,
    query_execution.user_agent,
    query_execution.sanitized_user_agent,
    query_execution.ip_address
   FROM (public.query_execution
     LEFT JOIN public.query ON ((query_execution.hash = query.query_hash)));


ALTER VIEW public.v_query_log OWNER TO "admin-rsi-metabase";

--
-- Name: v_subscriptions; Type: VIEW; Schema: public; Owner: admin-rsi-metabase
--

CREATE VIEW public.v_subscriptions AS
 WITH agg_recipients AS (
         SELECT pulse_channel_recipient.pulse_channel_id,
            string_agg((core_user.email)::text, ','::text) AS recipients
           FROM (public.pulse_channel_recipient
             LEFT JOIN public.core_user ON ((pulse_channel_recipient.user_id = core_user.id)))
          GROUP BY pulse_channel_recipient.pulse_channel_id
        )
 SELECT pulse.id AS entity_id,
    ('pulse_'::text || pulse.id) AS entity_qualified_id,
    pulse.created_at,
    pulse.updated_at,
    pulse.creator_id,
    pulse.archived,
    ('dashboard_'::text || pulse.dashboard_id) AS dashboard_qualified_id,
    pulse_channel.schedule_type,
    pulse_channel.schedule_day,
    pulse_channel.schedule_hour,
    pulse_channel.channel_type AS recipient_type,
    agg_recipients.recipients,
    pulse_channel.details AS recipient_external,
    pulse.parameters
   FROM ((public.pulse
     LEFT JOIN public.pulse_channel ON ((pulse.id = pulse_channel.pulse_id)))
     LEFT JOIN agg_recipients ON ((pulse_channel.id = agg_recipients.pulse_channel_id)))
  WHERE (pulse.alert_condition IS NULL);


ALTER VIEW public.v_subscriptions OWNER TO "admin-rsi-metabase";

--
-- Name: v_tables; Type: VIEW; Schema: public; Owner: admin-rsi-metabase
--

CREATE VIEW public.v_tables AS
 SELECT id AS entity_id,
    ('table_'::text || id) AS entity_qualified_id,
    created_at,
    updated_at,
    name,
    display_name,
    description,
    active,
    db_id AS database_id,
    schema,
    is_upload,
    entity_type,
    visibility_type,
    estimated_row_count,
    view_count,
    owner_email,
    owner_user_id
   FROM public.metabase_table;


ALTER VIEW public.v_tables OWNER TO "admin-rsi-metabase";

--
-- Name: v_task_runs; Type: VIEW; Schema: public; Owner: admin-rsi-metabase
--

CREATE VIEW public.v_task_runs AS
 SELECT id,
    run_type,
    entity_type,
    entity_id,
        CASE
            WHEN ((entity_type)::text = 'database'::text) THEN ('database_'::text || entity_id)
            WHEN ((entity_type)::text = 'card'::text) THEN ('card_'::text || entity_id)
            WHEN ((entity_type)::text = 'dashboard'::text) THEN ('dashboard_'::text || entity_id)
            ELSE (((entity_type)::text || '_'::text) || entity_id)
        END AS entity_qualified_id,
    started_at,
    ended_at,
        CASE
            WHEN (ended_at IS NOT NULL) THEN (EXTRACT(epoch FROM (ended_at - started_at)))::double precision
            ELSE NULL::double precision
        END AS duration_seconds,
    status,
    process_uuid,
    updated_at
   FROM public.task_run;


ALTER VIEW public.v_task_runs OWNER TO "admin-rsi-metabase";

--
-- Name: v_tasks; Type: VIEW; Schema: public; Owner: admin-rsi-metabase
--

CREATE VIEW public.v_tasks AS
 SELECT id,
    task,
    status,
    ('database_'::text || db_id) AS database_qualified_id,
    started_at,
    ended_at,
    ((duration)::double precision / (1000)::double precision) AS duration_seconds,
    task_details AS details,
    run_id
   FROM public.task_history;


ALTER VIEW public.v_tasks OWNER TO "admin-rsi-metabase";

--
-- Name: v_tenants; Type: VIEW; Schema: public; Owner: admin-rsi-metabase
--

CREATE VIEW public.v_tenants AS
 SELECT id AS tenant_id,
    ('tenant_'::text || id) AS entity_qualified_id,
    name,
    slug,
    is_active,
    attributes,
    created_at,
    updated_at,
    tenant_collection_id,
    ('collection_'::text || tenant_collection_id) AS tenant_collection_qualified_id
   FROM public.tenant;


ALTER VIEW public.v_tenants OWNER TO "admin-rsi-metabase";

--
-- Name: v_users; Type: VIEW; Schema: public; Owner: admin-rsi-metabase
--

CREATE VIEW public.v_users AS
 SELECT core_user.id AS user_id,
    ('user_'::text || core_user.id) AS entity_qualified_id,
    core_user.type,
        CASE
            WHEN ((core_user.type)::text = 'api-key'::text) THEN NULL::public.citext
            ELSE core_user.email
        END AS email,
    core_user.first_name,
    core_user.last_name,
    COALESCE((((core_user.first_name)::text || ' '::text) || (core_user.last_name)::text), (core_user.first_name)::text, (core_user.last_name)::text) AS full_name,
    core_user.date_joined,
    core_user.last_login,
    core_user.updated_at,
    core_user.is_superuser AS is_admin,
    core_user.is_active,
    core_user.sso_source,
    core_user.locale,
    core_user.tenant_id,
    ('tenant_'::text || core_user.tenant_id) AS tenant_qualified_id
   FROM public.core_user
UNION
 SELECT 0 AS user_id,
    'user_0'::text AS entity_qualified_id,
    'anonymous'::character varying AS type,
    NULL::public.citext AS email,
    'External'::character varying AS first_name,
    'User'::character varying AS last_name,
    'External User'::text AS full_name,
    NULL::timestamp with time zone AS date_joined,
    NULL::timestamp with time zone AS last_login,
    NULL::timestamp with time zone AS updated_at,
    false AS is_admin,
    NULL::boolean AS is_active,
    NULL::character varying AS sso_source,
    NULL::character varying AS locale,
    NULL::integer AS tenant_id,
    NULL::text AS tenant_qualified_id;


ALTER VIEW public.v_users OWNER TO "admin-rsi-metabase";

--
-- Name: view_log; Type: TABLE; Schema: public; Owner: admin-rsi-metabase
--

CREATE TABLE public.view_log (
    id integer NOT NULL,
    user_id integer,
    model character varying(16) NOT NULL,
    model_id integer NOT NULL,
    "timestamp" timestamp with time zone NOT NULL,
    metadata text,
    has_access boolean,
    context character varying(32),
    embedding_client character varying(254),
    embedding_sdk_version character varying(254),
    auth_method character varying(32),
    tenant_id integer,
    embedding_hostname character varying(512),
    embedding_path character varying(2048),
    user_agent character varying(512),
    ip_address character varying(45),
    sanitized_user_agent character varying(512),
    embedding_route character varying(64),
    metabase_version character varying(32),
    embedding_client_identifier character varying(254)
);


ALTER TABLE public.view_log OWNER TO "admin-rsi-metabase";

--
-- Name: COLUMN view_log.has_access; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.view_log.has_access IS 'Whether the user who initiated the view had read access to the item being viewed.';


--
-- Name: COLUMN view_log.context; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.view_log.context IS 'The context of the view, can be collection, question, or dashboard. Only for cards.';


--
-- Name: COLUMN view_log.embedding_client; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.view_log.embedding_client IS 'Used by the embedding team to track SDK usage';


--
-- Name: COLUMN view_log.embedding_sdk_version; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.view_log.embedding_sdk_version IS 'Used by the embedding team to track SDK version usage';


--
-- Name: COLUMN view_log.auth_method; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.view_log.auth_method IS 'Authentication method used (e.g. jwt, saml, api-key, public, guest, etc.)';


--
-- Name: COLUMN view_log.tenant_id; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.view_log.tenant_id IS 'Tenant ID of the user who generated this view';


--
-- Name: COLUMN view_log.embedding_hostname; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.view_log.embedding_hostname IS 'Hostname from Origin header, PII';


--
-- Name: COLUMN view_log.embedding_path; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.view_log.embedding_path IS 'Path from Referer header (query params stripped), PII';


--
-- Name: COLUMN view_log.user_agent; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.view_log.user_agent IS 'User-Agent header, PII';


--
-- Name: COLUMN view_log.ip_address; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.view_log.ip_address IS 'Client IP address, PII';


--
-- Name: COLUMN view_log.sanitized_user_agent; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.view_log.sanitized_user_agent IS 'Human-friendly parsed User-Agent (e.g. Browser (Chrome/Windows)), PII';


--
-- Name: COLUMN view_log.embedding_route; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.view_log.embedding_route IS 'API route surface (e.g. public, guest-embed, metabot, agent-api)';


--
-- Name: COLUMN view_log.metabase_version; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.view_log.metabase_version IS 'Metabase server version tag at time of insert';


--
-- Name: COLUMN view_log.embedding_client_identifier; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.view_log.embedding_client_identifier IS 'Identifier of the concrete embedding client (e.g. the data-app name) from the X-Metabase-Client-Identifier header';


--
-- Name: v_view_log; Type: VIEW; Schema: public; Owner: admin-rsi-metabase
--

CREATE VIEW public.v_view_log AS
 SELECT id,
    "timestamp",
    COALESCE(user_id, 0) AS user_id,
    model AS entity_type,
    model_id AS entity_id,
    (((model)::text || '_'::text) || model_id) AS entity_qualified_id,
    embedding_client,
    embedding_client_identifier,
    embedding_route,
        CASE
            WHEN ((embedding_client)::text ~~ '%-preview'::text) THEN true
            ELSE false
        END AS is_preview,
    has_access,
    context,
    embedding_sdk_version,
    metabase_version,
    auth_method,
    tenant_id,
    embedding_hostname,
    embedding_path,
    user_agent,
    sanitized_user_agent,
    ip_address
   FROM public.view_log;


ALTER VIEW public.v_view_log OWNER TO "admin-rsi-metabase";

