\\x2cfece853f9e37be93b0ff3dafc27459e696b6a42896a4e487393a9190c849f3	1043	{"lib/type":"mbql/query","stages":[{"lib/type":"mbql.stage/native","native":"WITH agg AS (\\n    SELECT\\n        source.\\"mes\\",\\n        source.\\"mes_nome\\",\\n\\t\\tSUM(source.\\"total_envolvidos\\") AS total\\n    FROM \\"main\\".\\"overview\\" AS source\\n\\n    WHERE 1 = 1\\n        [[AND source.\\"ano\\" = {{var_ano}}]]\\n        [[AND source.\\"regiao\\" = {{var_regiao}}]]\\n        [[AND source.\\"estado\\" = {{var_estado}}]]\\n        [[AND source.\\"tipo_area\\" = {{var_area}}]]\\n        [[AND source.\\"condicao_metereologica\\" = {{var_clima}}]]\\n\\n    GROUP BY\\n        source.\\"mes\\",\\n        source.\\"mes_nome\\"\\n)\\n\\nSELECT\\n    agg.\\"mes\\",\\n    agg.\\"mes_nome\\",\\n    agg.total,\\n\\t\\t\\n\\tAVG(agg.total) \\n\\t\\tOVER (\\n\\t\\t\\tORDER BY agg.\\"mes\\" \\n\\t\\t\\tROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW\\n\\t\\t) AS media,\\n\\t\\t\\n\\tSTDDEV(agg.total) \\n\\t\\tOVER () / \\n\\tAVG(agg.total) \\n\\t\\tOVER ()\\n\\tAS \\"Variação\\"\\nFROM agg\\n\\nORDER BY\\n    agg.\\"mes\\";","template-tags":[{"id":"05d16e0f-d902-4282-9122-b653f5139cbe","type":"number","name":"var_ano","display-name":"Ano"},{"id":"f83d72ee-cfe4-409f-9861-c236d2e961f5","type":"text","name":"var_regiao","display-name":"Região"},{"name":"var_estado","id":"af4ba3de-7483-4a5b-842a-eb15f785e859","type":"text","display-name":"Estado"},{"id":"ad1de61d-74b8-472b-85dd-5e45c1d63373","type":"text","name":"var_area","display-name":"Área"},{"id":"0f9c1505-6494-4d28-84f1-9c8e26e4cd92","type":"text","name":"var_clima","display-name":"Condição Clima"}]}],"database":3,"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true},"parameters":[{"id":"05d16e0f-d902-4282-9122-b653f5139cbe","type":"number/=","value":null,"target":["variable",["template-tag","var_ano"]]},{"id":"f83d72ee-cfe4-409f-9861-c236d2e961f5","type":"string/=","value":null,"target"